def initialize(species, level, owner = $player, withMoves = true, recheck_form = true)
  species_data = GameData::Species.get(species)
  @species          = species_data.species
  @form             = species_data.base_form
  @forced_form      = nil
  @time_form_set    = nil
  self.level        = level
  @steps_to_hatch   = 0
  heal_status
  @gender           = nil
  @shiny            = nil
  @ability_index    = nil
  @ability          = nil
  @nature           = nil
  @nature_for_stats = nil
  @item             = nil
  @mail             = nil
  @moves            = []
  reset_moves if withMoves
  @first_moves      = []
  @ribbons          = []
  @cool             = 0
  @beauty           = 0
  @cute             = 0
  @smart            = 0
  @tough            = 0
  @sheen            = 0
  @pokerus          = 0
  @name             = nil
  @happiness        = species_data.happiness
  @poke_ball        = :POKEBALL
  @markings         = []
  @iv               = {}
  @ivMaxed          = {}
  @ev               = {}
  GameData::Stat.each_main do |s|
    @iv[s.id]       = rand(IV_STAT_LIMIT + 1)
    @ev[s.id]       = 0
  end
  case owner
  when Owner
    @owner = owner
  when Player, NPCTrainer
    @owner = Owner.new_from_trainer(owner)
  else
    @owner = Owner.new(0, "", 2, 2)
  end
  @obtain_method    = 0   # Met
  @obtain_method    = 4 if $game_switches && $game_switches[Settings::FATEFUL_ENCOUNTER_SWITCH]
  @obtain_map       = ($game_map) ? $game_map.map_id : 0
  @obtain_text      = nil
  @obtain_level     = level
  @hatched_map      = 0
  @timeReceived     = Time.now.to_i
  @timeEggHatched   = nil
  @fused            = nil
  @personalID       = rand(2**16) | (rand(2**16) << 16)
  @hp               = 1
  @totalhp          = 1
  calc_stats
  if @form == 0 && recheck_form
    f = MultipleForms.call("getFormOnCreation", self)
    if f
      self.form = f
      reset_moves if withMoves
    end
  end
end

def species_data
  return GameData::Species.get_species_form(@species, form_simple)
end

def species=(species_id)
  new_species_data = GameData::Species.get(species_id)
  return if @species == new_species_data.species
  @species     = new_species_data.species
  default_form = new_species_data.default_form
  if default_form >= 0
    @form      = default_form
  elsif new_species_data.form > 0
    @form      = new_species_data.form
  end
  @forced_form = nil
  @gender      = nil if singleGendered?
  @level       = nil   # In case growth rate is different for the new species
  @ability     = nil
  calc_stats
end

def form=(value)
  oldForm = @form
  @form = value
  @ability = nil
  MultipleForms.call("onSetForm", self, value, oldForm)
  calc_stats
  $player&.pokedex&.register(self)
end

def setForm(value)
  oldForm = @form
  @form = value
  @ability = nil
  yield if block_given?
  MultipleForms.call("onSetForm", self, value, oldForm)
  calc_stats
  $player&.pokedex&.register(self)
end

def form_simple=(value)
  @form = value
  calc_stats
end

def level=(value)
  if value < 1 || value > GameData::GrowthRate.max_level
    raise ArgumentError.new(_INTL("The level number ({1}) is invalid.", value))
  end
  @exp = growth_rate.minimum_exp_for_level(value)
  @level = value
end

def exp=(value)
  @exp = value
  @level = nil
end

def growth_rate
  return GameData::GrowthRate.get(species_data.growth_rate)
end

def gender=(value)
  return if singleGendered?
  @gender = value if value.nil? || value == 0 || value == 1
end

def ability_index=(value)
  @ability_index = value
  @ability = nil
end

def ability
  return GameData::Ability.try_get(ability_id)
end

def ability=(value)
  return if value && !GameData::Ability.exists?(value)
  @ability = (value) ? GameData::Ability.get(value).id : value
end

def baseStats
  this_base_stats = species_data.base_stats
  ret = {}
  GameData::Stat.each_main { |s| ret[s.id] = this_base_stats[s.id] }
  return ret
end

def calc_stats
  base_stats = self.baseStats
  this_level = self.level
  this_IV    = self.calcIV
  # Format stat multipliers due to nature
  nature_mod = {}
  GameData::Stat.each_main { |s| nature_mod[s.id] = 100 }
  this_nature = self.nature_for_stats
  if this_nature
    this_nature.stat_changes.each { |change| nature_mod[change[0]] += change[1] }
  end
  # Calculate stats
  stats = {}
  GameData::Stat.each_main do |s|
    if s.id == :HP
      stats[s.id] = calcHP(base_stats[s.id], this_level, this_IV[s.id], @ev[s.id])
    else
      stats[s.id] = calcStat(base_stats[s.id], this_level, this_IV[s.id], @ev[s.id], nature_mod[s.id])
    end
  end
  hp_difference = stats[:HP] - @totalhp
  @totalhp = stats[:HP]
  self.hp = [@hp + hp_difference, 1].max if @hp > 0 || hp_difference > 0
  @attack  = stats[:ATTACK]
  @defense = stats[:DEFENSE]
  @spatk   = stats[:SPECIAL_ATTACK]
  @spdef   = stats[:SPECIAL_DEFENSE]
  @speed   = stats[:SPEED]
end

def initialize(hash)
  @id                 = hash[:id]
  @species            = hash[:species]            || @id
  @form               = hash[:form]               || 0
  @real_name          = hash[:real_name]          || "Unnamed"
  @real_form_name     = hash[:real_form_name]
  @real_category      = hash[:real_category]      || "???"
  @real_pokedex_entry = hash[:real_pokedex_entry] || "???"
  @pokedex_form       = hash[:pokedex_form]       || @form
  @types              = hash[:types]              || [:NORMAL]
  @base_stats         = hash[:base_stats]         || {}
  @evs                = hash[:evs]                || {}
  GameData::Stat.each_main do |s|
    @base_stats[s.id] = 1 if !@base_stats[s.id] || @base_stats[s.id] <= 0
    @evs[s.id]        = 0 if !@evs[s.id] || @evs[s.id] < 0
  end
  @base_exp           = hash[:base_exp]           || 100
  @growth_rate        = hash[:growth_rate]        || :Medium
  @gender_ratio       = hash[:gender_ratio]       || :Female50Percent
  @catch_rate         = hash[:catch_rate]         || 255
  @happiness          = hash[:happiness]          || 70
  @moves              = hash[:moves]              || []
  @tutor_moves        = hash[:tutor_moves]        || []
  @egg_moves          = hash[:egg_moves]          || []
  @abilities          = hash[:abilities]          || []
  @hidden_abilities   = hash[:hidden_abilities]   || []
  @wild_item_common   = hash[:wild_item_common]   || []
  @wild_item_uncommon = hash[:wild_item_uncommon] || []
  @wild_item_rare     = hash[:wild_item_rare]     || []
  @egg_groups         = hash[:egg_groups]         || [:Undiscovered]
  @hatch_steps        = hash[:hatch_steps]        || 1
  @incense            = hash[:incense]
  @offspring          = hash[:offspring]          || []
  @evolutions         = hash[:evolutions]         || []
  @height             = hash[:height]             || 1
  @weight             = hash[:weight]             || 1
  @color              = hash[:color]              || :Red
  @shape              = hash[:shape]              || :Head
  @habitat            = hash[:habitat]            || :None
  @generation         = hash[:generation]         || 0
  @flags              = hash[:flags]              || []
  @mega_stone         = hash[:mega_stone]
  @mega_move          = hash[:mega_move]
  @unmega_form        = hash[:unmega_form]        || 0
  @mega_message       = hash[:mega_message]       || 0
  @pbs_file_suffix    = hash[:pbs_file_suffix]    || ""
end

def self.new_from_trainer(trainer)
  validate trainer => [Player, NPCTrainer]
  return new(trainer.id, trainer.name, trainer.gender, trainer.language)
end

def initialize(id, name, gender, language)
  validate id => Integer, name => String, gender => Integer, language => Integer
  @id = id
  @name = name
  @gender = gender
  @language = language
end

def initialize(move_id)
  @id   = GameData::Move.get(move_id).id
  @ppup = 0
  @pp   = total_pp
end

def id=(value)
  @id = GameData::Move.get(value).id
  @pp = @pp.clamp(0, total_pp)
end

def self.call(func, pkmn, *args)
  sp = @@formSpecies[pkmn.species]
  return nil if !sp || !sp[func]
  return sp[func].call(pkmn, *args)
end

def hp=(value)
  @hp = value.clamp(0, @totalhp)
  heal_status if @hp == 0
  @ready_to_evolve = false if @hp == 0
end

def hasType?(type)
  type = GameData::Type.get(type).id
  return self.types.include?(type)
end

def super_shiny=(value)
  @super_shiny = value
  @shiny = true if @super_shiny
end

def nature=(value)
  return if value && !GameData::Nature.exists?(value)
  @nature = (value) ? GameData::Nature.get(value).id : value
  calc_stats if !@nature_for_stats
end

def nature_for_stats=(value)
  return if value && !GameData::Nature.exists?(value)
  @nature_for_stats = (value) ? GameData::Nature.get(value).id : value
  calc_stats
end

module GameData
  class Nature
    attr_reader :id
    attr_reader :real_name
    attr_reader :stat_changes

    DATA = {}

    extend ClassMethodsSymbols
    include InstanceMethods

    def self.load; end
    def self.save; end

    def initialize(hash)
      @id           = hash[:id]
      @real_name    = hash[:name]         || "Unnamed"
      @stat_changes = hash[:stat_changes] || []
    end

    # @return [String] the translated name of this nature
    def name
      return _INTL(@real_name)
    end
  end
end

